// We use the Verus standard library for vector proofs.
use vstd::prelude::*;

verus! {

    /// Swap the elements at indices `i` and `j` of `arr`.
    ///
    /// Requirements:
    ///   - `i < arr.len()`
    ///   - `j < arr.len()`
    ///
    /// Postcondition:
    ///   - The resulting vector view `arr@` is the same as the old view
    ///     except that positions `i` and `j` have been exchanged.
    pub fn swap(arr: &mut Vec<i32>, i: usize, j: usize)
        requires
            i < arr.len(),
            j < arr.len(),
        ensures
            // arr@ is the "view" (immutable snapshot) of arr.
            // We update position i to the old[j], and position j to the old[i].
            arr@ == old(arr@).update(i, old(arr@)[j])
                            .update(j, old(arr@)[i])
    {
        // If the indices are equal, no work is needed.
        if i == j {
            return;
        }

        // Perform the usual three‐step swap.
        let tmp: i32 = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }

}